<?php use App\Core\Helpers as H; use App\Services\NotificationService; ?>
<header class="dashboard-heading"><div><h1>Notifications</h1><p class="muted">Unread updates are highlighted.</p></div><form method="post" action="/notifications/read-all"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><button>Mark all read</button></form></header>
<?php if(!$notifications):?><section class="card empty-state"><h2>You're all caught up</h2><p>Order, seller, and administrative updates for your account will appear here.</p><a class="btn" href="/dashboard">Return to dashboard</a></section><?php endif;?>
<div class="notification-list"><?php foreach($notifications as $n):$url=NotificationService::safeActionUrl($n['action_url']);?><article class="card notification <?=$n['read_at']?'':'unread'?>"><div class="dashboard-heading"><div><span class="status-badge <?=$n['read_at']?'neutral':'ok'?>"><?=$n['read_at']?'Read':'Unread'?></span><h2><?=H::e($n['title'])?></h2><p><?=H::e($n['message'])?></p><small><?=H::e($n['created_at'])?></small></div><div class="quick-actions"><?php if($url):?><a class="btn" href="<?=H::e($url)?>">View</a><?php endif;?><?php if(!$n['read_at']):?><form method="post" action="/notifications/<?=(int)$n['id']?>/read"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><button>Mark read</button></form><?php endif;?></div></div></article><?php endforeach;?></div>
<nav class="pagination" aria-label="Notification pages"><?php if($page>1):?><a href="?page=<?=$page-1?>">Previous</a><?php endif;?> <span>Page <?=$page?> of <?=$pages?></span><?php if($page<$pages):?><a href="?page=<?=$page+1?>">Next</a><?php endif;?></nav>
